app.patch('/api/bookings/:id/status',auth,limits.write,async(req,res)=>{const b=await Bookings.byId(req.params.id);if(!b)return res.status(404).json({error:'Not found'});const p=await Professionals.byId(b.professionalId);if(!canEditBooking(req.user,b,p))return res.status(403).json({error:'Δεν επιτρέπεται.'});const status=str(req.body.status,30);if(!['pending','clarification','quoted','accepted','completed','cancelled'].includes(status))return res.status(400).json({error:'Invalid status'});const updated=await Bookings.update(b.id,{status});await Notifications.create(req.user.role==='professional'?b.patientId:p.userId,'booking',`Ενημέρωση κράτησης: ${status}`,b.service);res.json({booking:updated})})
