app.post('/api/bookings/:id/message',auth,limits.write,async(req,res)=>{const b=await Bookings.byId(req.params.id);if(!b)return res.status(404).json({error:'Not found'});const p=await Professionals.byId(b.professionalId);if(!canViewBooking(req.user,b,p))return res.status(403).json({error:'Δεν επιτρέπεται.'});const text=str(req.body.text,1500);const updated=await Bookings.addMessage(b,req.user,text);await Notifications.create(req.user.id===b.patientId?p.userId:b.patientId,'message','Νέο μήνυμα MELEO',text.slice(0,180));res.json({booking:updated})})
app.post('/api/bookings/:id/quote',auth,requireRole('professional'),limits.write,async(req,res)=>{const b=await Bookings.byId(req.params.id),p=await Professionals.byId(b?.professionalId);if(!b||p.userId!==req.user.id)return res.status(404).json({error:'Not found'});const price=Math.max(0,Math.min(5000,Number(req.body.price??req.body.amount)||0));if(!price)return res.status(400).json({error:'Δώσε τελικό κόστος.'});await Bookings.update(b.id,{status:'quoted',proposedPrice:price});if(req.body.note||req.body.message)await Bookings.addMessage(b,req.user,str(req.body.note||req.body.message,1000),'quote');await Notifications.create(b.patientId,'quote','Νέα πρόταση τελικού κόστους',`${price.toFixed(2)}€`);res.json({booking:await Bookings.byId(b.id)})})
app.post('/api/bookings/:id/quote-decision',auth,requireRole('patient'),limits.write,async(req,res)=>{const b=await Bookings.byId(req.params.id);if(!b||b.patientId!==req.user.id)return res.status(404).json({error:'Not found'});const accept=Boolean(req.body.accept);const updated=await Bookings.update(b.id,accept?{status:'accepted',agreedPrice:b.proposedPrice}:{status:'clarification'});const p=await Professionals.byId(b.professionalId);await Notifications.create(p.userId,'quote',accept?'Η πρόταση κόστους έγινε αποδεκτή':'Η πρόταση χρειάζεται νέα συζήτηση',b.service);res.json({booking:updated})})
app.post('/api/bookings/:id/review',auth,requireRole('patient'),limits.write,async(req,res)=>{const b=await Bookings.byId(req.params.id);if(!b||!canReviewBooking(req.user,b))return res.status(400).json({error:'Αξιολόγηση επιτρέπεται μόνο μετά από ολοκληρωμένη επίσκεψη.'});const rating=Math.max(1,Math.min(5,Math.round(Number(req.body.rating)||0))),comment=str(req.body.comment,1000);try{await tx(async c=>{await c.query(`INSERT INTO reviews(id,booking_id,patient_id,professional_id,rating,comment) VALUES($1,$2,$3,$4,$5,$6)`,[id('rev'),b.id,req.user.id,b.professionalId,rating,comment]);await c.query(`UPDATE professionals SET reviews_count=(SELECT count(*) FROM reviews WHERE professional_id=$1),rating=(SELECT coalesce(avg(rating),0) FROM reviews WHERE professional_id=$1),updated_at=now() WHERE id=$1`,[b.professionalId])})}catch(err){if(err.code==='23505')return res.status(409).json({error:'Η επίσκεψη έχει ήδη αξιολογηθεί.'});throw err}const p=await Professionals.byId(b.professionalId);await Notifications.create(p.userId,'review','Νέα αξιολόγηση',`${rating}/5 ⭐`);res.json({ok:true})})

